async function iniciar(){const cfg=window.PORTAL_CONFIG||{};
 if(window.MOCK_API)S.api=window.MOCK_API;
 else{if(!cfg.SUPABASE_URL||/COLE_AQUI/.test(cfg.SUPABASE_URL+cfg.SUPABASE_ANON_KEY)){$('#app').innerHTML=`<div class="setup">${LOGO()}<h1 class="mt">Falta configurar o portal</h1><p>Abra o arquivo <b>config.js</b> e cole a <b>Project URL</b> e a chave <b>anon/publishable</b> do seu projeto no Supabase (Project Settings › API). Depois publique de novo.</p></div>`;return}
  if(!window.supabase){$('#app').innerHTML='<div class="setup"><h1>Sem conexão</h1><p>Não foi possível carregar a biblioteca do Supabase. Verifique a internet e recarregue a página.</p></div>';return}
  S.api=makeSupabaseApi(cfg)}
 let recup=/type=(invite|recovery)/.test(location.hash);if(recup)setTimeout(()=>novaSenhaModal(true),800);S.api.onAuth&&S.api.onAuth(ev=>{if(ev==='PASSWORD_RECOVERY'&&!$('#ns1')){recup=true;setTimeout(()=>novaSenhaModal(true),300)}});
 try{await carregarUsuario()}catch(e){toast(e.message,true)}
 render();if(S.user&&!recup)await go('inicio')}
