async function admPatch(patch){const {r}=D();Object.assign(r,(await S.api.update('admissoes',{id:r.id},patch))[0])}
FIELD.push(async ev=>{const t=ev.target;if(!t.dataset.cd&&!t.dataset.ad&&!t.dataset.gx)return false;if(ev.type!=='change')return true;const {r}=D();
 if(t.dataset.cd){const c=Object.assign({},r.candidato);c[t.dataset.cd]=t.value;await admPatch({candidato:c})}
 else if(t.dataset.gx){const g=Object.assign({},r.guia_exame);g[t.dataset.gx]=t.value;await admPatch({guia_exame:g})}
 else{let v=t.value;if(t.type==='number')v=v===''?null:+v;if(v==='')v=null;await admPatch({[t.dataset.ad]:v})}return true});
