 admExameOk:async()=>{const {r,docs}=D();if(!(r.guia_exame||{}).emitida_em){$('#aprErr').textContent='Imprima a guia de encaminhamento primeiro.';return}if(!r.aso_resultado||!r.aso_data){$('#aprErr').textContent='Informe o resultado e a data do exame.';return}if(r.aso_resultado==='Inapto'){$('#aprErr').textContent='Candidato inapto: use "Encerrar".';return}
  if(!docs.find(d=>d.tipo==='aso'&&d.arquivo_path)){$('#aprErr').textContent='Anexe o ASO admissional.';return}await mudaEtapa(r,'contab','Registrou exame admissional',r.aso_resultado+' em '+fD(r.aso_data));reload()},
 admFicha:()=>{const {r}=D();openModal(`<h2>Ficha preliminar de admissão</h2><div class="docprev">${fichaPreliminar(r)}</div><div class="modal-actions"><button class="btn" data-act="admFichaWord">Baixar Word</button><button class="btn" data-act="admFichaPrint">Imprimir / salvar PDF</button><button class="btn" data-act="close">Fechar</button></div>`,true)},
 admFichaPrint:()=>{closeModal();docPrint(fichaPreliminar(D().r));evento('Imprimiu ficha preliminar',sa(D().r))},admFichaWord:()=>{const {r}=D();docWord('Ficha preliminar - '+(r.candidato.nome||sa(r)),fichaPreliminar(r).replace(/#printArea /g,''));evento('Baixou ficha preliminar',sa(r))},
