 admEmail:()=>{const {r}=D();const em=$('#ctEm').value.trim();const c=r.candidato||{};const body=`Prezados,\n\nSegue a ficha preliminar de admissão para registro no eSocial (S-2200):\n\nNome: ${c.nome||''}\nCPF: ${c.cpf||''}\nCargo: ${funcaoNome(r.funcao_id)}\nAdmissão prevista: ${fD(r.inicio_previsto)}\nObra: ${obraNome(r.obra_id)}\n\nAnexos: ficha preliminar, documentos pessoais e ASO admissional.\n\nAtenciosamente,\n${S.user.nome}\nAvante Engenharia`;
  location.href='mailto:'+encodeURIComponent(em)+'?subject='+encodeURIComponent('Admissão '+(c.nome||'')+' – '+funcaoNome(r.funcao_id))+'&body='+encodeURIComponent(body)},
