const vencPill=d=>{if(!d)return '<span class="muted">—</span>';const n=diasEntre(dk(T0),String(d).slice(0,10));return n<0?pill(fD(d)+' · vencido','bad'):n<=30?pill(fD(d),'warn'):fD(d)};
crud({id:'veiculos',tabela:'veiculos',titulo:'Veículos e equipamentos',novo:'+ Novo veículo',sub:'Frota própria e alugada. Defina o consumo de referência para o portal apontar abastecimentos fora do padrão.',ordem:['placa'],filtroVeic:false,
 campos:[{c:'placa',l:'Placa / identificação',req:1,up:1,ph:'ABC1D23'},{c:'tipo',l:'Tipo',t:'sel',op:TIPOS_VEIC,req:1},{c:'propriedade',l:'Propriedade',t:'sel',op:['Próprio','Alugado'],req:1},
  {c:'marca',l:'Marca'},{c:'modelo',l:'Modelo'},{c:'ano',l:'Ano',t:'num'},
  {c:'combustivel',l:'Combustível',t:'sel',op:COMBUST,req:1},{c:'medidor',l:'Mede uso por',t:'sel',op:[['km','Quilômetros (hodômetro)'],['horas','Horas (horímetro)']],req:1},{c:'tanque_litros',l:'Capacidade do tanque (l)',t:'num'},
  {c:'consumo_referencia',l:'Consumo de referência (km/l ou l/h)',t:'num'},{c:'km_inicial',l:'Km / horas na entrada na frota',t:'num'},{c:'situacao',l:'Situação',t:'sel',op:['Ativo','Em manutenção','Parado','Devolvido','Vendido'],req:1},
  {c:'obra_id',l:'Obra atual',t:'obra'},{c:'condutor_id',l:'Condutor principal',t:'func'},{c:'cor',l:'Cor'},
  {c:'locadora',l:'Locadora',so:r=>1},{c:'contrato',l:'Nº do contrato de locação'},{c:'valor_locacao_mensal',l:'Valor mensal da locação (R$)',t:'money'},
  {c:'inicio_locacao',l:'Início da locação',t:'date'},{c:'fim_locacao',l:'Fim da locação',t:'date'},{c:'franquia_km_mes',l:'Franquia de km por mês',t:'num'},
  {c:'licenciamento_venc',l:'Licenciamento vence em',t:'date'},{c:'seguro_venc',l:'Seguro vence em',t:'date'},{c:'seguradora',l:'Seguradora'},
  {c:'renavam',l:'Renavam'},{c:'chassi',l:'Chassi',w:2},{c:'observacao',l:'Observações',t:'area',w:3}],colsForm:3,
 def:()=>({propriedade:'Próprio',combustivel:'Diesel S10',medidor:'km',situacao:'Ativo',tipo:'Caminhonete'}),
 valida:(r,id)=>{if((LG.vs||[]).some(v=>v.placa===r.placa&&v.id!==id))return 'Já existe um veículo com esta placa.';if(r.propriedade==='Alugado'&&!r.valor_locacao_mensal)return 'Para veículo alugado, informe o valor mensal da locação (entra no custo da frota).';return null},
 kpis:(L,all)=>{const at=all.filter(v=>!['Devolvido','Vendido'].includes(v.situacao));const al=at.filter(v=>v.propriedade==='Alugado');
  return kc('Frota ativa',at.length,`${at.length-al.length} próprios · ${al.length} alugados`)+kc('Locação mensal',BRL(al.reduce((s,v)=>s+(+v.valor_locacao_mensal||0),0)),'soma dos contratos ativos')+kc('Em manutenção / parados',at.filter(v=>v.situacao!=='Ativo').length,'',at.some(v=>v.situacao!=='Ativo')?'warn':'ok')+kc('Documentos vencendo',at.filter(v=>[v.licenciamento_venc,v.seguro_venc,v.propriedade==='Alugado'?v.fim_locacao:null].some(d=>d&&diasEntre(dk(T0),String(d).slice(0,10))<=30)).length,'licenciamento, seguro ou contrato em 30 dias','')},
 cols:[['Veículo',v=>`<a class="lp-link" data-act="go" data-r="veiculo" data-id="${v.id}"><b>${esc(v.placa)}</b></a><div class="small muted">${esc([v.tipo,v.marca,v.modelo,v.ano].filter(Boolean).join(' · '))}</div>`],['Propriedade',v=>v.propriedade==='Alugado'?`${pill('Alugado','warn')}<div class="small muted">${esc(v.locadora||'')}${v.valor_locacao_mensal?' · '+BRL(+v.valor_locacao_mensal)+'/mês':''}</div>`:pill('Próprio','ok')],['Combustível',v=>esc(v.combustivel)+(v.consumo_referencia?`<div class="small muted">ref. ${fN1(+v.consumo_referencia,1)} ${unid(v).c}</div>`:'')],['Obra / condutor',v=>esc(obraNome(v.obra_id)||'—')+`<div class="small muted">${esc(fNome(v.condutor_id))}</div>`],['Licenciamento',v=>vencPill(v.licenciamento_venc)],['Seguro',v=>vencPill(v.seguro_venc)],['Situação',v=>pill(v.situacao,v.situacao==='Ativo'?'ok':['Devolvido','Vendido'].includes(v.situacao)?'':'warn')]]});

