function perLog(k){if(/^\d{4}-\d{2}$/.test(k)){const[y,m]=k.split('-').map(Number);return {ini:new Date(y,m-1,1),fim:new Date(y,m,0),lbl:mesLbl(k)}}
 const n=k==='ult3'?3:12;return {ini:new Date(T0.getFullYear(),T0.getMonth()-n+1,1),fim:new Date(T0.getFullYear(),T0.getMonth()+1,0),lbl:'Últimos '+n+' meses'}}
const dentro=(d,P)=>{const x=pdk(String(d).slice(0,10));return x>=P.ini&&x<=P.fim};
function locacaoPer(v,P){if(v.propriedade!=='Alugado'||!v.valor_locacao_mensal)return 0;const ini=v.inicio_locacao?pdk(v.inicio_locacao):null,fim=v.fim_locacao?pdk(v.fim_locacao):null;let tot=0;
 for(let m=new Date(P.ini.getFullYear(),P.ini.getMonth(),1);m<=P.fim;m=new Date(m.getFullYear(),m.getMonth()+1,1)){const mf=new Date(m.getFullYear(),m.getMonth()+1,0);const a=new Date(Math.max(m,P.ini,ini||m)),b=new Date(Math.min(mf,P.fim,fim||mf,T0>mf?mf:T0));if(b<a)continue;const dias=Math.round((b-a)/864e5)+1;tot+=(+v.valor_locacao_mensal)*dias/mf.getDate()}return tot}
function leituras(v,d){const sus=new Set(consumoSeg((d.ab||[]).filter(a=>a.veiculo_id===v.id)).filter(x=>segSuspeito(x,v)).map(x=>x.id));return [].concat((d.ab||[]).filter(a=>a.veiculo_id===v.id&&a.km!=null&&!sus.has(a.id)).map(a=>({data:String(a.data).slice(0,10),km:+a.km})),(d.mn||[]).filter(a=>a.veiculo_id===v.id&&a.km!=null).map(a=>({data:String(a.data).slice(0,10),km:+a.km})),(d.oc||[]).filter(a=>a.veiculo_id===v.id&&a.km!=null).map(a=>({data:String(a.data).slice(0,10),km:+a.km}))).sort((a,b)=>a.data.localeCompare(b.data)||a.km-b.km)}
function kmPer(v,d,P){const L=leituras(v,d);const em=L.filter(x=>dentro(x.data,P));if(!em.length)return 0;const antes=L.filter(x=>pdk(x.data)<P.ini);const base=antes.length?Math.max(...antes.map(x=>x.km)):(v.km_inicial!=null?+v.km_inicial:Math.min(...em.map(x=>x.km)));return Math.max(0,Math.max(...em.map(x=>x.km))-base)}
