// ---------- valor por extenso (para contratos)
function extenso(v){v=Math.round((+v||0)*100)/100;const U=['','um','dois','três','quatro','cinco','seis','sete','oito','nove','dez','onze','doze','treze','quatorze','quinze','dezesseis','dezessete','dezoito','dezenove'],D=['','','vinte','trinta','quarenta','cinquenta','sessenta','setenta','oitenta','noventa'],C=['','cento','duzentos','trezentos','quatrocentos','quinhentos','seiscentos','setecentos','oitocentos','novecentos'];
 const ate999=n=>{if(n===0)return '';if(n===100)return 'cem';const c=Math.floor(n/100),r=n%100;const p=[];if(c)p.push(C[c]);if(r){if(r<20)p.push(U[r]);else{const dd=Math.floor(r/10),u=r%10;p.push(D[dd]+(u?' e '+U[u]:''))}}return p.join(' e ')};
 const inteiro=n=>{if(n===0)return 'zero';const g=[[1e9,'bilhão','bilhões'],[1e6,'milhão','milhões'],[1e3,'mil','mil'],[1,'','']];const p=[];let r=n;for(const[b,s,pl]of g){const q=Math.floor(r/b);r=r%b;if(!q)continue;p.push(b===1e3&&q===1?'mil':ate999(q)+(s?' '+(q===1?s:pl):''))}
  if(p.length>1){const ult=n%1000;return p.slice(0,-1).join(', ')+((ult<=100||ult%100===0)?' e ':', ')+p[p.length-1]}return p[0]};
 const r=Math.floor(v),c=Math.round((v-r)*100);let s='';if(r)s=inteiro(r)+(r===1?' real':(r%1e6===0?' de reais':' reais'));if(c)s+=(r?' e ':'')+ate999(c)+(c===1?' centavo':' centavos');return s||'zero real'}

