 ctGerar:async()=>{const {n,c}=D();const ms=(await S.api.select('modelos_documento',{order:['nome']})).filter(x=>x.tipo==='contrato'&&(!x.usar_para||x.usar_para===n.segmento||x.usar_para==='Todos'));
  if(!ms.length){openModal(`<h2>Nenhum modelo de contrato</h2><p>Cadastre o modelo em Comercial › Modelos de contrato. Ao receber a minuta da Avante, ela vira o modelo padrão.</p><div class="modal-actions"><button class="btn" data-act="close">Fechar</button>${perm('modelos','incluir')?`<button class="btn primary" data-act="go" data-r="modelos">Abrir modelos</button>`:''}</div>`);return}
  S._ctMs=ms;S._ctN=n;S._ctC=c;ctPrev(ms[0].id)},
