FIELD.push(ev=>{if(ev.target.id==='ctMod'&&ev.type==='change'){ctPrev(ev.target.value);return true}return false});

// ---------- modelos
const CT_MODELO_INICIAL=`# CONTRATO DE EMPREITADA GLOBAL PARA CONSTRUÇÃO DE UNIDADE RESIDENCIAL

## CLÁUSULA PRIMEIRA - DAS PARTES
**CONTRATANTE:** {{cliente.qualificacao}}{{conjuge.qualificacao}}.

**CONTRATADA:** {{empresa.qualificacao}}.

## CLÁUSULA SEGUNDA - DO OBJETO
O presente contrato tem por objeto a construção, pela CONTRATADA, em regime de empreitada global (material e mão de obra), de unidade residencial com área construída de {{obra.area_m2}} m², no imóvel situado em {{obra.endereco}}, {{obra.cidade}}, {{obra.lote_quadra}}, matrícula nº {{obra.matricula}}, conforme projetos, memorial descritivo, orçamento e cronograma físico-financeiro aprovados pelo agente financeiro, que integram este contrato.

## CLÁUSULA TERCEIRA - DO PREÇO E DA FORMA DE PAGAMENTO
O valor total da obra é de {{valor}} ({{valor_extenso}}), pago da seguinte forma:
1. {{recursos_proprios}} ({{recursos_proprios_extenso}}) com recursos próprios do CONTRATANTE, conforme cronograma acordado;
2. {{valor_financiado}} ({{valor_financiado_extenso}}) com recursos do financiamento contratado junto ao {{banco}}, liberados diretamente à CONTRATADA conforme as medições de obra realizadas pela engenharia do agente financeiro.

## CLÁUSULA QUARTA - DO PRAZO
A obra será executada no prazo de {{obra.prazo_meses}} meses, contados da liberação da primeira parcela do financiamento e da emissão da ordem de início, observado o cronograma físico-financeiro aprovado.

## CLÁUSULA QUINTA - DAS OBRIGAÇÕES DA CONTRATADA
- Executar a obra conforme os projetos, o memorial descritivo e as normas técnicas aplicáveis;
- Manter responsável técnico habilitado e a obra regular perante os órgãos competentes;
- Cumprir as normas de segurança do trabalho e responder pelos encargos trabalhistas e previdenciários de seus empregados;
- Entregar a obra concluída, limpa e em condições de habitabilidade.

## CLÁUSULA SEXTA - DAS OBRIGAÇÕES DO CONTRATANTE
- Efetuar os pagamentos de recursos próprios nas datas acordadas;
- Fornecer a documentação necessária ao financiamento e às licenças;
- Não alterar o projeto sem acordo prévio e por escrito, ajustando-se preço e prazo quando houver acréscimos.

## CLÁUSULA SÉTIMA - DA GARANTIA
A CONTRATADA responde pela solidez e segurança da obra pelo prazo de 5 (cinco) anos, nos termos do art. 618 do Código Civil.

## CLÁUSULA OITAVA - DA RESCISÃO
O descumprimento de qualquer cláusula autoriza a rescisão deste contrato pela parte prejudicada, mediante notificação por escrito, respondendo a parte infratora pelas perdas e danos.

## CLÁUSULA NONA - DO FORO
Fica eleito o foro da comarca de {{cidade_contrato}} para dirimir quaisquer questões oriundas deste contrato.

E, por estarem justas e contratadas, as partes assinam o presente instrumento em 2 (duas) vias de igual teor, na presença de duas testemunhas.

{{cidade_contrato}}, {{data_extenso}}.

{{assinaturas}}`;
PAGES.modelos={async load(){return {L:(await S.api.select('modelos_documento',{order:['nome']})).filter(x=>x.tipo==='contrato')}},
 html(){const L=D().L||[];const ed=perm('modelos','editar')||perm('modelos','incluir');
  return `<h1>Modelos de contrato</h1><p class="sub">O texto do contrato com campos automáticos entre chaves duplas, por exemplo {{cliente.nome}}. Ao gerar o contrato, o portal preenche com os dados do cliente e da obra.</p>
  <div class="toolbar"><span class="sp"></span>${ed?`<button class="btn primary" data-act="mdNovo">+ Novo modelo</button>`:''}</div>
  <div class="card tablewrap"><table><thead><tr><th>Modelo</th><th>Usar em</th><th>Versão</th><th>Atualizado</th><th></th></tr></thead><tbody>${L.map(m=>`<tr><td><b>${esc(m.nome)}</b></td><td>${esc(m.usar_para||'Todos')}</td><td>v${m.versao}</td><td>${fDT(m.atualizado_em)}</td><td>${ed?`<button class="btn sm" data-act="mdEditar" data-id="${m.id}">Editar</button>`:''}</td></tr>`).join('')||`<tr><td colspan="5" class="muted">Nenhum modelo. ${ed?'<button class="btn sm" data-act="mdInicial">Criar modelo provisório para começar</button>':''}</td></tr>`}</tbody></table></div>`}};
function mdModal(m){m=m||{nome:'',usar_para:'B2C',texto:'',versao:0};openModal(`<h2>${m.id?'Editar modelo':'Novo modelo'}</h2><div class="grid" style="grid-template-columns:2fr 1fr;gap:0 12px"><div><label>Nome do modelo</label><input id="mdN" value="${esc(m.nome)}"></div><div><label>Usar em</label><select id="mdU">${['B2C','B2B','Todos'].map(x=>`<option ${x===(m.usar_para||'Todos')?'selected':''}>${x}</option>`).join('')}</select></div></div>
 <div class="grid" style="grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:12px;margin-top:10px"><div><label>Texto do contrato</label><textarea id="mdT" rows="22" style="font-family:ui-monospace,Consolas,monospace;font-size:12.5px">${esc(m.texto)}</textarea><p class="small muted">## Título da cláusula · - item de lista · 1. item numerado · **negrito**</p></div>
 <div><label>Campos automáticos (clique para inserir)</label><div class="md-vars">${CT_VARS.map(([k,l])=>`<button class="md-var" data-act="mdIns" data-k="${k}" title="${esc(l)}">{{${k}}}<span>${esc(l)}</span></button>`).join('')}</div></div></div>
 <div id="err" class="err"></div><div class="modal-actions"><button class="btn" data-act="close">Cancelar</button><button class="btn primary" data-act="mdSalvar" data-id="${m.id||''}">Salvar${m.id?' (nova versão v'+(m.versao+1)+')':''}</button></div>`,true)}
Object.assign(ACT,{mdNovo:()=>mdModal(),mdEditar:t=>mdModal((D().L||[]).find(x=>x.id===t.dataset.id)),
 mdInicial:async()=>{await S.api.insert('modelos_documento',[{nome:'Contrato de empreitada global · obra residencial financiada (PROVISÓRIO)',tipo:'contrato',usar_para:'B2C',texto:CT_MODELO_INICIAL,versao:1}]);toast('Modelo provisório criado. Substitua pelo texto da minuta da Avante.');reload()},
 mdIns:t=>{const ta=$('#mdT');const s=ta.selectionStart||ta.value.length;const tok='{{'+t.dataset.k+'}}';ta.value=ta.value.slice(0,s)+tok+ta.value.slice(ta.selectionEnd||s);ta.focus();ta.selectionStart=ta.selectionEnd=s+tok.length},
 mdSalvar:async t=>{const id=t.dataset.id;const r={nome:$('#mdN').value.trim(),usar_para:$('#mdU').value,texto:$('#mdT').value,tipo:'contrato',atualizado_em:new Date().toISOString()};if(!r.nome||!r.texto.trim()){$('#err').textContent='Informe nome e texto.';return}
  const bad=[...r.texto.matchAll(/\{\{\s*([\w.]+)\s*\}\}/g)].map(x=>x[1]).filter(k=>!CT_VARS.some(v=>v[0]===k));if(bad.length&&!confirm('Campos desconhecidos: '+[...new Set(bad)].join(', ')+'. Eles aparecerão em amarelo no contrato. Salvar mesmo assim?'))return;
  if(id){const m=(D().L||[]).find(x=>x.id===id);r.versao=(m.versao||1)+1;await S.api.update('modelos_documento',{id},r)}else{r.versao=1;await S.api.insert('modelos_documento',[r])}closeModal();toast('Modelo salvo.');reload()}});

