FIELD.push(async ev=>{const t=ev.target;if(t.id!=='fnImpF'||ev.type!=='change')return false;const f=t.files[0];if(!f)return true;let tx=await f.text();if(tx.charCodeAt(0)===0xFEFF)tx=tx.slice(1);const nrm=s=>String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().trim();
 const ls=tx.split(/\r?\n/).filter(l=>l.trim());const sep=ls[0].includes(';')?';':',';const H=ls[0].split(sep).map(h=>nrm(h).replace(/\s+/g,'_'));const ix=k=>H.indexOf(k);
 const dt=s=>{s=String(s||'').trim();let m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);if(m)return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);return m?m[0]:null};
 const obras=S.ref.obras.map(o=>({id:o.id,n:nrm(o.nome)})).sort((a,b)=>b.n.length-a.n.length);const ok=[],er=[];let semObra=0;
 ls.slice(1).forEach((l,i)=>{const c=l.split(sep).map(x=>x.trim().replace(/^"|"$/g,''));const g=k=>ix(k)>=0?c[ix(k)]:'';const venc=dt(g('vencimento')),valor=numBR(g('valor'));if(!venc||valor==null){er.push(`Linha ${i+2}: vencimento ou valor inválido`);return}
  const cc=nrm(g('centro_custo'));const ob=cc?obras.find(o=>cc.includes(o.n)):null;if(cc&&!ob)semObra++;const cta=g('conta')?(FN.ct||[]).find(x=>nrm(x.nome)===nrm(g('conta'))):null;
  ok.push({venc,valor,fav:g('favorecido')||null,desc:g('descricao')||g('favorecido')||'Importado',cat:g('categoria')||null,doc:g('documento')||null,obra:ob?ob.id:null,conta:cta?cta.id:null,pg:dt(g('data_pagamento')),vp:numBR(g('valor_pago'))})});
 S._fnImp=ok;$('#fnImpPrev').innerHTML=`<b>${ok.length}</b> linha(s) prontas.${semObra?` ${semObra} com centro de custo que não corresponde a nenhuma obra cadastrada (ficam sem obra).`:''}${er.length?`<br><span style="color:var(--bad)">${er.length} com problema:</span><br>${er.slice(0,6).map(esc).join('<br>')}`:''}`;document.querySelector('[data-act="fnImpOk"]').disabled=!ok.length;return true});

